export function translator(locale) {
  const table = DICT[locale] || DICT.en;
  return (key, vars = {}) => {
    const template = table[key] ?? DICT.en[key];
    if (template === undefined) return key;
    return template.replace(/\{(\w+)\}/g, (_, k) => (k in vars ? String(vars[k]) : `{${k}}`));
  };
}
